      if (nothingMade(e) || e.code === 412) { u.status = back; u.error = `Nothing was made (${e.code}: ${e.text}). Sent again next tick.`; }
      else if (e.code === 403) { u.status = 'error'; u.error = `Muse refused: ${e.text}. Change the ${plan.kind === 'image' ? 'notes' : 'line or motion'}, then set the status to ${back}.`; }
      else if (mayBeMade(e)) { u.status = 'check job'; u.error = `${e.code || 'no code'}: ${e.text}. Muse may already have made it: check GET /jobs/{jobid}?history=true before you set the status back.`; }
      else { u.status = 'error'; u.error = explain(e, 'The job failed'); }
      out.push({ json: { update: u } }); return;
    }
    return;  // still running: nothing to write
  }
  // A submit (after an upload when the step was "upload").
  if (plan.step === 'upload') {
    const up = $('Batch upload').itemMatching(i).json;
    const ue = apiErr(up);
    if (ue || !up.assetId) { const e = ue || { code: 0, text: 'no assetId' };
      u.error = explain(e, 'The photo could not be uploaded'); if ([400, 401, 404, 413].includes(e.code)) u.status = 'error';
      out.push({ json: { update: u } }); return; }
  }
  if (j.jobid && j.status === 'started') {
    if (plan.kind === 'image') { u.status = 'restoring'; u.restore_jobid = j.jobid; u.notes = plan.notes || ''; }
    else { u.status = 'rendering'; u.video_jobid = j.jobid; }
    u.error = ''; out.push({ json: { update: u } }); return;
  }
  const e = apiErr(j) || { code: 0, text: 'no job id in the answer' };
  if (nothingMade(e) || e.code === 412) u.error = `Nothing was made (${e.code}: ${e.text}). Sent again next tick.`;
  else if (mayBeMade(e)) { u.status = 'check job'; u.error = `${e.code || 'no answer'}: ${e.text}. The job may have started: check GET /jobs before you set the status back.`; }
  else { u.status = 'error'; u.error = explain(e, 'The job could not be started'); }
  out.push({ json: { update: u } });
});
return out;

// The columns to write: the row result, plus the Drive link when the file was saved.
return $input.all().map((it, i) => {
  if (it.json.update) return { json: it.json.update };
  const res = $('Row result').itemMatching(i).json;
  const u = { ...res.update };
  if (it.json.id) u.drive_link = `https://drive.google.com/file/d/${it.json.id}/view`;
  else u.error = `The video is done but the Drive upload failed (${(it.json.error && it.json.error.message) || 'no answer'}). video_asset still has it.`;
  return { json: u };
});
